import { cli } from '@jackwener/opencli/registry';

cli({
    site: 'nowcoder',
    name: 'detail',
    access: 'read',
    description: 'Post detail view (supports ID / UUID / URL)',
    domain: 'www.nowcoder.com',
    args: [
        { name: 'id', positional: true, required: true, help: 'Post ID, UUID, or URL' },
    ],
    columns: ['title', 'author', 'school', 'content', 'likes', 'comments', 'views', 'time', 'location', 'url', 'content_complete', 'content_access'],
    pipeline: [
        { navigate: 'https://www.nowcoder.com' },
        { evaluate: `(async () => {
  const raw = \${{ args.id | json }};
  const input = String(raw).trim();
  const base = 'https://gw-c.nowcoder.com';
  const strip = (html) => String(html || '')
    .replace(/<br\\s*\\/?\\s*>|<\\/(?:p|div|li|h[1-6])\\s*>/gi, '\\n')
    .replace(/<[^>]+>/g, '')
    .replace(/&nbsp;/g, ' ').replace(/&lt;/g, '<').replace(/&gt;/g, '>')
    .replace(/&amp;/g, '&').replace(/\\n[ \\t]*\\n+/g, '\\n\\n').trim();

  let id = input;
  if (/^https?:\\/\\//i.test(input)) {
    const url = new URL(input);
    if (!/^(?:www\\.)?nowcoder\\.com$/i.test(url.hostname) || url.username || url.password)
      throw new Error('Expected a nowcoder.com post URL');
    const match = url.pathname.match(/^\\/(?:discuss\\/(\\d+)|feed\\/main\\/detail\\/([a-f0-9]{32}))\\/?$/i);
    if (!match) throw new Error('Unsupported Nowcoder post URL');
    id = match[1] || match[2];
  }
  if (!/^\\d+$/.test(id) && !/^[a-f0-9]{32}$/i.test(id))
    throw new Error('Expected a numeric Nowcoder post ID, a 32-character UUID, or a post URL');

  async function readDetail(kind) {
    const response = await fetch(base + '/api/sparta/detail/' + kind + '/detail/' + id,
      {credentials: 'include'});
    let result;
    try { result = await response.json(); }
    catch { throw new Error('Nowcoder detail HTTP ' + response.status + ': response is not valid JSON'); }
    if (!response.ok)
      throw new Error('Nowcoder detail HTTP ' + response.status + ': ' + (result.msg || response.statusText));
    if (result.success && result.data) return result.data;
    // A missing post is the only response that permits the other numeric post type.
    // Preserve login, verification and other API errors instead of hiding them.
    if (/内容不存在|帖子不存在|post not found/i.test(String(result.msg || ''))) return null;
    throw new Error(result.msg || 'Nowcoder detail returned an incomplete response');
  }

  let data;
  if (/^[a-f0-9]{32}$/i.test(id)) {
    data = await readDetail('moment-data');
  } else {
    data = await readDetail('content-data');
    if (!data) data = await readDetail('moment-data');
  }
  if (!data) throw new Error('Post not found: ' + id);

  const user = data.userBrief || {};
  const freq = data.frequencyData || {};
  const timestamp = data.createdAt ?? data.createTime;
  const restricted = data.hasLook === false || data.showMessage?.showContent === false;
  return [{
    title: data.title || '(untitled)',
    author: user.nickname || '',
    school: user.educationInfo || '',
    content: strip(data.content || ''),
    content_complete: !restricted,
    content_access: restricted ? (data.blogZhuanlan ? 'paid_preview' : 'restricted') : 'full',
    likes: freq.likeCnt || 0,
    comments: freq.commentCnt || freq.totalCommentCnt || 0,
    views: freq.viewCnt || 0,
    time: timestamp != null ? new Date(timestamp).toISOString().slice(0, 19) : '',
    location: data.ip4Location || '',
    url: /^https?:\\/\\//i.test(input) ? input :
      'https://www.nowcoder.com/' + (/^\\d+$/.test(id) ? 'discuss/' : 'feed/main/detail/') + id,
  }];
})()
` },
    ],
});

